===  fact
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "snapshotId",
  "relation",
  "resolution",
  "sourceUniverse",
  "targetUniverse",
  "producerClosure",
  "payloadSchemaDigest",
  "payloadDigest",
  "anchors",
  "confidenceMillionths"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "snapshotId": {
   "type": "string",
   "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "relation": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "resolution": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "sourceUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "targetUniverse": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "h-identity",
    "domainSet": "native-semantic-universe"
   }
  },
  "producerClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "payloadSchemaDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "raw-artifact",
    "artifact": "the exact full bytes of foundation/relation-payload-schemas.v2.json, the registered relation payload schema document"
   }
  },
  "payloadDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "canonical-record",
    "record": {
     "payloadClass": "relation",
     "keyedBy": [
      "relation"
     ],
     "schemaDigestField": "payloadSchemaDigest"
    }
   }
  },
  "anchors": {
   "type": "array",
   "maxItems": 100000,
   "uniqueItems": true,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "path",
     "blobDigest",
     "startByte",
     "endByte"
    ],
    "properties": {
     "path": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "blobDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
       "representation": "raw-artifact",
       "artifact": "the exact retained source blob bytes named by path in the snapshot inventory"
      }
     },
     "startByte": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     },
     "endByte": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     }
    }
   },
   "x-opensip-order": "canonical-set"
  },
  "confidenceMillionths": {
   "type": "integer",
   "minimum": 0,
   "maximum": 1000000
  }
 }
}
